sp_widget.client_script:
api.controller = function($location) {
    var c = this;

    c.statusFilter = '';
    c.priorityFilter = '';

    c.viewDetail = function(record) {
        $location.search({id: 'x_839216_public_0_detail', sys_id: record.sys_id});
    };

    c.applyFilter = function() {
        c.server.get({
            action: 'filter',
            statusFilter: c.statusFilter,
            priorityFilter: c.priorityFilter
        }).then(function(response) {
            c.data.records = response.data.records;
        });
    };

    c.clearFilters = function() {
        c.statusFilter = '';
        c.priorityFilter = '';
        c.applyFilter();
    };

    c.getStatusClass = function(status) {
        if (!status) return 'label-default';
        var s = status.toLowerCase();
        if (s === 'approved') return 'label-success';
        if (s === 'in_progress' || s === 'in progress') return 'label-warning';
        if (s === 'rejected') return 'label-danger';
        if (s === 'submitted') return 'label-info';
        return 'label-default';
    };

    c.getPriorityClass = function(priority) {
        if (!priority) return 'label-default';
        var p = priority.toLowerCase();
        if (p === 'critical') return 'label-danger';
        if (p === 'high') return 'label-warning';
        if (p === 'medium') return 'label-info';
        return 'label-default';
    };

    c.getUrgencyClass = function(urgency) {
        if (!urgency) return 'label-default';
        var u = urgency.toLowerCase();
        if (u === 'critical') return 'label-danger';
        if (u === 'high') return 'label-warning';
        if (u === 'medium') return 'label-info';
        return 'label-default';
    };

    c.getTypeIcon = function(type) {
        if (!type) return 'glyphicon-file';
        var t = type.toLowerCase();
        if (t.indexOf('inspection') > -1) return 'glyphicon-search';
        if (t.indexOf('medical') > -1) return 'glyphicon-heart';
        if (t.indexOf('vaccination') > -1) return 'glyphicon-plus-sign';
        if (t.indexOf('appointment') > -1) return 'glyphicon-calendar';
        if (t.indexOf('emergency') > -1) return 'glyphicon-flash';
        return 'glyphicon-file';
    };
};

sp_widget.css:
/* List Panel */
.sp-list-panel {
    border: 1px solid #e8edf2;
    border-radius: 8px;
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.04);
    overflow: hidden;
}
.sp-list-heading {
    background: #f8fafb;
    border-bottom: 1px solid #e8edf2;
    padding: 14px 20px;
}
.sp-list-heading .panel-title {
    font-size: 16px;
    font-weight: 600;
    color: #1a2b3c;
    display: flex;
    align-items: center;
    gap: 10px;
}
.sp-count-badge {
    background: #0d8a8f;
    color: #ffffff;
    font-size: 12px;
    padding: 3px 8px;
    border-radius: 10px;
    margin-left: auto;
}

/* Filter Row */
.sp-filter-row {
    background: #f8fafb;
    border-bottom: 1px solid #e8edf2;
    padding: 12px 20px;
}
.sp-filter-select {
    font-size: 13px;
    height: 34px;
    border-radius: 4px;
    border: 1px solid #d4dbe3;
}
.sp-filter-select:focus {
    border-color: #0d8a8f;
    box-shadow: 0 0 0 2px rgba(13, 138, 143, 0.1);
}
.sp-clear-btn {
    margin-top: 0;
    font-size: 12px;
    height: 34px;
}

/* Table */
.sp-card-body-flush {
    padding: 0;
}
.sp-request-table {
    margin-bottom: 0;
}
.sp-request-table thead th {
    background: #f8fafb;
    font-size: 11px;
    font-weight: 600;
    color: #5a6b7c;
    text-transform: uppercase;
    letter-spacing: 0.4px;
    border-bottom: 2px solid #e8edf2;
    padding: 10px 14px;
    white-space: nowrap;
}
.sp-request-table tbody td {
    font-size: 13px;
    padding: 12px 14px;
    vertical-align: middle;
    border-top: 1px solid #f1f5f9;
}
.sp-clickable-row {
    cursor: pointer;
    transition: background 0.15s ease;
}
.sp-clickable-row:hover {
    background: #f0fdfa !important;
}
.sp-number-link {
    color: #0d8a8f;
    font-size: 13px;
}
.sp-clickable-row:hover .sp-number-link {
    text-decoration: underline;
}
.sp-type-indicator {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 13px;
    color: #3a4b5c;
}
.sp-type-indicator .glyphicon {
    font-size: 12px;
    color: #0d8a8f;
}
.sp-approval-text {
    font-size: 13px;
    color: #5a6b7c;
}
.sp-date-col {
    font-size: 12px;
    white-space: nowrap;
}

/* Empty State */
.sp-empty-state {
    padding: 64px 24px;
}
.sp-empty-icon {
    font-size: 48px;
    margin-bottom: 16px;
    display: block;
    opacity: 0.3;
    color: #8a9aab;
}
.sp-empty-title {
    font-size: 18px;
    font-weight: 600;
    color: #1a2b3c;
    margin-bottom: 8px;
}

@media (max-width: 767px) {
    .sp-filter-row .col-sm-3 {
        margin-bottom: 8px;
    }
}

sp_widget.script:
(function() {
    var table = 'x_839216_public_0_health_service_request_v1';
    data.title = options.title || 'Health Service Requests';
    data.records = [];
    data.filterByUser = options.filter_by_user === 'true' || options.filter_by_user === true;

    var gr = new GlideRecord(table);

    if (data.filterByUser) {
        gr.addQuery('sys_created_by', gs.getUserName());
    }

    // Handle server-side filtering
    if (input && input.action === 'filter') {
        if (input.statusFilter) {
            gr.addQuery('u_status', input.statusFilter);
        }
        if (input.priorityFilter) {
            gr.addQuery('u_priority', input.priorityFilter);
        }
    }

    gr.orderByDesc('sys_created_on');
    gr.setLimit(100);
    gr.query();
    while (gr.next()) {
        data.records.push({
            sys_id: gr.getUniqueValue(),
            number: gr.getValue('number') + '',
            u_request_type: gr.getDisplayValue('u_request_type') + '',
            u_urgency: gr.getDisplayValue('u_urgency') + '',
            u_priority: gr.getDisplayValue('u_priority') + '',
            u_status: gr.getDisplayValue('u_status') + '',
            u_approval_status: gr.getDisplayValue('u_approval_status') + '',
            assignment_group: gr.getDisplayValue('assignment_group') + '',
            u_citizen_name: gr.getValue('u_citizen_name') + '',
            sys_created_on: gr.getDisplayValue('sys_created_on') + ''
        });
    }
})();
